<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {localDateTime,measurementPercent} from '../lib/form-values.mjs'
import {studentApi,type Measurements} from '../api/student-capabilities'
import type {Measurement} from '../api/backend-types'
import DetailPopover from './DetailPopover.vue'
const props=defineProps<{assetType:'report'|'direction_plan';version:number;subjectId:string;dimensions:{key:string;label:string}[]}>()
const emit=defineEmits<{saved:[]}>()
const records=ref<Measurements>({items:[],history:[]}),busy=ref(false),error=ref(''),editing=ref(false),status=ref('')
const key=ref(''),value=ref<number>(),min=ref(0),max=ref(100),threshold=ref<number>(),source=ref(''),method=ref(''),when=ref('')
const current=computed(()=>records.value.items.find(b=>b.asset_type===props.assetType&&b.version===props.version&&b.subject_id===props.subjectId)?.measurements??[])
const normalized=(m:Measurement)=>measurementPercent(m)
const chartRecords=computed(()=>current.value.filter(m=>normalized(m)!==null))
const loading=ref(false)
const points=computed(()=>chartRecords.value.map((m,i)=>{const a=i/chartRecords.value.length*Math.PI*2-Math.PI/2,r=normalized(m)!*.85;return `${110+Math.cos(a)*r},${110+Math.sin(a)*r}`}).join(' '))
const trendKey=ref('')
const trend=computed(()=>{const active=current.value.find(m=>m.key===(trendKey.value||current.value[0]?.key));if(!active)return [];return records.value.items.filter(b=>b.asset_type===props.assetType&&(props.assetType==='report'||b.subject_id===props.subjectId)).flatMap(b=>b.measurements.filter(m=>m.key===active.key&&m.label===active.label&&m.source===active.source&&m.method===active.method&&m.minimum===active.minimum&&m.maximum===active.maximum&&m.origin===active.origin).map(m=>({version:b.version,value:m.value,source:m.source}))).sort((a,b)=>a.version-b.version)})
async function load(){loading.value=true;error.value='';try{records.value=await studentApi.measurements()}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
watch(()=>[props.version,props.subjectId],load)
watch(key,v=>{const m=current.value.find(m=>m.key===v);value.value=m?.value;min.value=m?.minimum??0;max.value=m?.maximum??100;threshold.value=m?.threshold??undefined;source.value=m?.source??'';method.value=m?.method??'';when.value=localDateTime(m?.measured_at);status.value='';error.value=''})
async function save(){if(busy.value||loading.value)return;error.value='';status.value='';if(typeof value.value!=='number'||measurementPercent({value:value.value,minimum:min.value,maximum:max.value})===null){error.value='最大值须大于最小值，原始数值须在量表范围内。';return}busy.value=true;try{const measurement:Measurement={key:key.value,label:props.dimensions.find(d=>d.key===key.value)?.label??key.value,value:value.value,minimum:min.value,maximum:max.value,threshold:typeof threshold.value==='number'?threshold.value:null,source:source.value,method:method.value,measured_at:new Date(when.value).toISOString(),origin:'self_report'};await studentApi.saveMeasurements({asset_type:props.assetType,version:props.version,subject_id:props.subjectId,measurements:[...current.value.filter(m=>m.key!==key.value),measurement]});await load();emit('saved');status.value=error.value?'记录已保存，最新数据暂未取得，请重新读取。':'量表记录已保存，来源为本人录入。'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="measurement-panel"><div class="ws-section-head"><h3>量表、门槛与版本对照</h3><DetailPopover v-model="editing" title="录入已有量表结果" label="补充量表记录" side="right"><template #trigger>补充量表记录</template><form class="measurement-form" @submit.prevent="save"><fieldset :disabled="busy||loading"><p>请录入已有测评或资料中的数值。此入口标记为本人录入，不会变成系统核验结果。</p><label class="ws-field">维度<select v-model="key" required><option value="">选择维度</option><option v-for="d in dimensions" :key="d.key" :value="d.key">{{d.label}}</option></select></label><label class="ws-field">原始数值<input v-model.number="value" type="number" step="any" required/></label><label class="ws-field">量表最小值<input v-model.number="min" type="number" step="any" required/></label><label class="ws-field">量表最大值<input v-model.number="max" type="number" step="any" required/></label><label class="ws-field">目标门槛（可留空）<input v-model.number="threshold" type="number" step="any"/></label><label class="ws-field">来源或证据<input v-model="source" required maxlength="1000"/></label><label class="ws-field">量表名称与计算方法<input v-model="method" required maxlength="300"/></label><label class="ws-field">测量时间<input v-model="when" type="datetime-local" required/></label><p v-if="error" class="ws-field-error" role="alert">{{error}}</p><button class="btn" :disabled="busy||loading">{{busy?'正在保存…':'保存量表记录'}}</button><p v-if="status" role="status">{{status}}</p></fieldset></form></DetailPopover></div><p v-if="loading" class="ws-muted" role="status">正在读取量化记录…</p><p v-if="error" class="ws-field-error" role="alert">{{error}} <button class="ws-text-button" :disabled="loading||busy" @click="load">重新读取</button></p><p v-if="!current.length&&!loading&&!error" class="ws-muted">当前版本尚无量化记录。可补充带来源的测评结果；不会根据文字判断猜分。</p><div v-if="current.length" class="measurement-content"><svg v-if="chartRecords.length>=3" viewBox="0 0 220 220" class="measurement-radar" role="img" aria-label="已记录维度的归一化雷达图"><circle v-for="r in [28,56,85]" :key="r" cx="110" cy="110" :r="r" fill="none" stroke="var(--c-border)"/><polygon :points="points" fill="var(--c-primary-weak)" stroke="var(--c-primary)" stroke-width="2"/><text x="110" y="212" text-anchor="middle" fill="currentColor" font-size="10">仅绘制已有记录，按下表顺序</text></svg><div class="measurement-bars"><div v-for="m in current" :key="m.key"><div class="ws-section-head"><span>{{m.label}}</span><b>{{m.value}} / {{m.maximum}}</b></div><meter v-if="normalized(m)!==null" :min="m.minimum??0" :max="m.maximum??100" :value="m.value" :aria-label="m.label"/><small v-if="m.threshold!=null">门槛 {{m.threshold}} · {{m.value>=m.threshold?'达到':'尚未达到'}}</small><DetailPopover :label="m.label+'：查看来源'" :title="m.label+' · 来源'" side="right"><template #trigger>依据</template><p>{{m.source}}</p><p>{{m.method}} · {{m.minimum}}—{{m.maximum}}</p><p>{{m.origin==='assessment'?'测评记录':m.origin==='external'?'外部资料':'本人录入'}} · {{new Date(m.measured_at).toLocaleString()}}</p></DetailPopover></div></div></div><template v-if="current.length"><label class="ws-field">跨版本对照<select v-model="trendKey"><option value="">{{current[0]?.label}}</option><option v-for="m in current" :key="m.key" :value="m.key">{{m.label}}</option></select></label><p class="ws-muted">仅比较维度、来源、量表方法和范围相同的记录。</p><div class="measurement-trend"><span v-for="t in trend" :key="t.version">第 {{t.version}} 版 <strong>{{t.value}}</strong></span></div><p v-if="trend.length<2" class="ws-muted">目前不足两个可比较版本。</p></template></section></template>
<style scoped>.measurement-form fieldset{display:grid;gap:12px;border:0;padding:0;margin:0;min-width:0}.measurement-panel>.ws-section-head{flex-wrap:wrap;gap:12px}.measurement-panel{margin:20px 0}.measurement-content{display:flex;gap:24px;align-items:center}.measurement-radar{width:220px;max-width:100%;flex:none}.measurement-bars{flex:1;min-width:0;display:grid;gap:14px}meter{width:100%;accent-color:var(--c-primary)}.measurement-form{display:grid;gap:12px}.measurement-trend{display:flex;gap:20px;flex-wrap:wrap;margin:16px 0}.measurement-trend span{display:grid;gap:5px}.measurement-trend strong{color:var(--c-primary)}@media(max-width:700px){.measurement-content{flex-direction:column}.measurement-bars{width:100%}}</style>
